+const fill = (text, params) => text.replace(/\{(\w+)\}/g, (_, k) => (k in params ? String(params[k]) : `{${k}}`));
+
 /** Supported languages, the first is the fallback. */
 export const LANGUAGES = Object.keys(MESSAGES);

 /** The message for `key` in `lang` (falling back to English), with {params} filled in. */
 export function t(key, lang = "en", params = {}) {
   const text = MESSAGES[lang]?.[key] ?? MESSAGES.en[key] ?? key;
-  return text.replace(/\{(\w+)\}/g, (_, k) => (k in params ? String(params[k]) : `{${k}}`));
+  const terms = TERMS[lang] ?? {};
+  const local = { ...params };
+  if ("state" in params) local.state = terms.state?.[params.state] ?? params.state;
+  if ("action" in params) local.action = terms.action?.[params.action] ?? params.action;
+  if ("reason" in params) local.reason = fill(terms.reason?.[params.reason] ?? params.reason, params);
+  return fill(text, local);
+}
+
+/** The best supported language in an Accept-Language header, else `fallback`. */
+export function pickLanguage(header, fallback) {
+  if (typeof header !== "string") return fallback;
+  let best = fallback;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [tag, ...attrs] = part.split(";").map((s) => s.trim());
+    const lang = tag.toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    const qAttr = attrs.find((a) => /^q=/i.test(a));
+    const q = qAttr ? Number(qAttr.slice(2)) : 1;
+    if (q > bestQ && q <= 1) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best;
 }

